#!/usr/bin/env python3
"""Generate Flutter's offline catalog from the shared server snapshot.

Sources and redistribution notices: server/job_geography.json and
server/geography-LICENSES.txt. No network request is needed to regenerate.
"""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
data = json.loads((root / 'server/job_geography.json').read_text())


def dart(value):
    return json.dumps(value, ensure_ascii=False).replace('$', r'\$')


rows = [
    '// Generated by tools/generate_job_geography.py; do not edit manually.',
    '// Unicode CLDR / Google libphonenumber; see server/geography-LICENSES.txt.',
    'const jobCountryData = <String, List<String>>{',
]
for country in data['countries']:
    values = [country[k] for k in ['name', 'englishName', 'currency', 'dialCode', 'nationalPrefix']]
    values += country['aliases']
    rows.append(f'  {dart(country["code"])}: [{", ".join(map(dart, values))}],')
rows += ['};', '', 'const jobCurrencyNames = <String, String>{']
rows += [f'  {dart(code)}: {dart(name)},' for code, name in data['currencies'].items()]
rows += ['};', '']
(root / 'lib/features/jobs/domain/job_geography_data.dart').write_text('\n'.join(rows))
